function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const { z } = require("zod");
z.config(z.locales.it());
const r = z.string().email().safeParse("not-an-email");
if (r.success) broken("invalid email was accepted");
const msg = r.error.issues[0] && r.error.issues[0].message;
if (typeof msg !== "string") broken("no issue message");
if (msg.startsWith("Invalid ")) symptom("z.locales.it invalid_format message is untranslated English");
if (!msg.startsWith("Input non valido: ")) broken("unexpected message: " + msg);
console.log("OK: z.locales.it invalid_format message is Italian: " + msg);

